export async function writeWorkbookFullName() {
    await Excel.run(async (context) => {

        // Get workbook full name (path + filename)
        const fullName = Office.context.document.url;
        const valueToWrite = fullName && fullName.length > 0
            ? fullName
            : "(Unsaved workbook)";

        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const range = context.workbook.getSelectedRange();

        range.load("values");
        await context.sync();

        const currentValue = range.values[0][0];

        // If cell is empty → write immediately
        if (!currentValue || currentValue.toString().trim() === "") {
            range.values = [[valueToWrite]];
            await context.sync();
            return;
        }

        // Otherwise → ask user for confirmation
        const userConfirmed = await showOverwritePrompt();

        if (userConfirmed) {
            range.values = [[valueToWrite]];
            await context.sync();
        }
    });
}

// Helper for writeWorkbookFullName()
function showOverwritePrompt() {
    return new Promise((resolve) => {

        Office.context.ui.displayDialogAsync(
            "https://localhost:3000/dialogs/overwritePrompt.html",
            { height: 30, width: 30 },

            (result) => {
                const dialog = result.value;

                dialog.addEventHandler(Office.EventType.DialogMessageReceived, (msg) => {
                    dialog.close();
                    resolve(msg.message === "yes");
                });

                dialog.addEventHandler(Office.EventType.DialogEventReceived, () => {
                    resolve(false);
                });
            }
        );
    });
}

// Called from ribbon button "Create Template (old)"
export async function createUDFTemplate() {
    await Excel.run(async (context) => {

        //========================================================
        // Test UDFs
        //========================================================

        // 1. Create a new worksheet
        const shtMrgTemplate = context.workbook.worksheets.add("TestUDFs");

        // 2. Parameters range
        const param = shtMrgTemplate.getRange("S1:T7");
        param.values = [["formatId:", "short"], ["customFormat:", "YYYY-MM-DDDD"], ["yearLength:", "4"], ["ordinal:", "false"], ["isAll:", "false"], ["short(day):", "true"], ["short(month):", "true"]]

        // 3. Header row
        const header = shtMrgTemplate.getRange("A1:M1");
        header.values = [["ID", "LastName", "FirstName", "Lang", "DOB", "mrgDOB", "mrgDayName", "mrgDayNum", "mrgOrd", "mrgMthSht", "mrgMthLng", "mrgMthNum", "mrgYear"]];
        header.format.font.bold = true;
        header.format.fill.color = "#D9E1F2";   // light blue
        header.format.autofitColumns();

        // 4. Function row (replace formulas with your UDFs)
        const rngMrgTemplate = shtMrgTemplate.getRange("A2:M3");
        const strNameSpace = "MLTK;"
        rngMrgTemplate.formulas = [
            ["=row()-1", "=\"Doe\"&row()-1", "=\"John\"&row()-1", "fr-Ca", "=TODAY()", "=MLTK.FORMATDATE($E2,$D2,$T$1,$T$2)", "=MLTK.GETDAYNAME($E2,$D2,$T$6)", "=MLTK.GETDAYNUM($E2)",  "=MLTK.GETORDINAL(DAY($E2),$D2, $T$4)", "=MLTK.GETMONTHNAME($E2,$D2,$T$7)", "=MLTK.GETMONTHNAME($E2,$D2)","=MLTK.GETMONTHNUM($E2)", "=MLTK.GETYEARNAME($E2, $T$3)"],
            ["=row()-1", "=\"Doe\"&row()-1", "=\"John\"&row()-1", "en-US",  "=TODAY()", "=MLTK.FORMATDATE($E3,$D3,$T$1,$T$2)", "=MLTK.GETDAYNAME($E3,$D3,$T$6)", "=MLTK.GETDAYNUM($E3)",  "=MLTK.GETORDINAL(DAY($E3),$D3, $T$4)", "=MLTK.GETMONTHNAME($E3,$D3,$T$7)", "=MLTK.GETMONTHNAME($E3,$D3)","=MLTK.GETMONTHNUM($E3)", "=MLTK.GETYEARNAME($E3, $T$3)"],
        ];
        shtMrgTemplate.getUsedRange().format.autofitColumns();
        shtMrgTemplate.getUsedRange().format.autofitRows();


        //========================================================
        // General
        //========================================================
        
        // Activate the sheet
        shtMrgTemplate.activate();

        await context.sync();
    });
}

