// src/functions/templates/loader.js

// import other templates as you create them
import { templateDemo } from  "../templates/templates/templateDemoUDF"
import { templateUDF } from "./templates/templateUDF";

import TestData from "../../data/UDF_TestDataDates.json";
import TestDataNumbers from "../../data/UDF_TestDataNumbers.json";

import { validLocaleList } from "mltk-core";

// safe logger reference (place at top of files that use mltkLogger)
if (typeof window.mltkLogger === "undefined") {
  window.mltkLogger = {
    log: () => {},
    debug: () => {},
    info: () => {},
    warn: (...args) => { mltkLogger.warn(...args); },
    error: (...args) => { mltkLogger.error(...args); }
  };
}

// Global variable that represents the number of records in the TestData dbase (src/data/UDF_TestData.json)
const _dbaseRecNum = TestData.length;
const _dbaseNumbersRecNum = TestDataNumbers.length;

// Global variable that will receive the data & formula range top row number later in the fillDown loop of applyUDFTemplate()
let _firstDataRow = 0;
let _lastDataRow = 0;

const TemplateRegistry = {
    templateDemo,
    templateUDF,
};

// Returns the template object
export function loadTemplateById(id) {
  return TemplateRegistry[id] || null;
}

/*Applies a template to the current workbook.
 * Behavior:
 *  - Get the worksheet named sheetDef.name (creates it if missing)
 *  - Clears the used range of that sheet (so repeated runs are clean)
 *  - Writes the template cell values as found in the template
 */
export async function applyUDFTemplate(template, consMsg) {
  await Excel.run(async (context) => {
    // Defensive: ensure template has expected structure
    if (!template || !Array.isArray(template.sheets) || template.sheets.length === 0) {
      throw new Error("Invalid template structure.");
    }
    let actionMsg = "Template updated";

    for (const sheetDef of template.sheets) {
      const sheetName = sheetDef.name || "Sheet1";

      // Try to get the sheet; if it doesn't exist, create it
      let sheet;
      try {
        sheet = context.workbook.worksheets.getItem(sheetName);
        sheet.load("name");
        await context.sync();
      } catch (e) {
        // sheet not found -> create it
        sheet = context.workbook.worksheets.add(sheetName);
        sheet.load("name");
        await context.sync();
        actionMsg = "Template created"
        }

      // Clear the used range on the sheet so the template is applied cleanly
      try {
        const used = sheet.getUsedRangeOrNullObject();
        used.load("address, values");
        await context.sync();

        if (!used.isNullObject) {
          used.clear(Excel.ClearApplyTo.contents);
        }
      } catch (e) {
        // If clearing fails, log and continue — not fatal for this simple template
        mltkLogger.debug("Warning: failed to clear used range on sheet", sheetName, e);
      }

      // Apply cells from the template
      if (sheetDef.cells) {
        const entries = Object.entries(sheetDef.cells); // [["A1", {...}], ["B1", {...}], ["A2", {...}]]
        for (const [address, def] of entries) {

          const def = sheetDef.cells[address];
          try {
            const range = sheet.getRange(address);
            if (def.formula !== undefined && def.formula !== null) {
              range.formulas = [[def.formula]];
            } else if (def.formulaR1C1 !== undefined) {
              range.formulasR1C1 = [[def.formulaR1C1]];
            } else if (def.value !== undefined) {
              range.values = [[def.value]];
            }

            // Formatting: This gives three ways to specify formatting:
            if (def.format) {
              let fmt = def.format;

              // 1. Use a named style that is format is a string: format: "HeaderStyle" 
              if (typeof fmt === "string") {
                fmt = template.styles?.[fmt];
              }

              // 2. Use a named style with overrides that is format is an object with "use",  then merge it:  format: { use: "HeaderStyle", overrides: { fontSize: 18 } } 
              if (typeof fmt === "object" && fmt.use) {
                const base = template.styles?.[fmt.use] || {};
                fmt = { ...base, ...fmt.overrides };
              }

              // 3. Use a raw formatting object that is: format: { bold: true, fill: "#000000" } 
              if (fmt) {
                applyFormatting(range, fmt);
              }
            }

          } catch (e) {
            mltkLogger.debug(`Failed to write to ${sheetName}!${address}`, e);
          }
        }

        if (sheetDef.fillDown) {
          for (const fd of sheetDef.fillDown) {

            const formulaRow = parseInt(fd.from.match(/\d+/)[0]);
            _firstDataRow = formulaRow;
            const startFillRow = formulaRow + 1;

            if (sheetDef.isDatesDemo) {
            const lastFillRow = startFillRow + _dbaseRecNum - 2;
            _lastDataRow = lastFillRow;
            }
            if (sheetDef.isNumbersDemo) {
            const lastFillRow = startFillRow + _dbaseNumbersRecNum - 2;
            _lastDataRow = lastFillRow;
            }

            let toAddress = fd.to.replace("*", _lastDataRow.toString());

            const source = sheet.getRange(fd.from);
            const target = sheet.getRange(toAddress);
            source.load("address");
            target.load("address");
            await context.sync();

            target.copyFrom(source, Excel.RangeCopyType.formulas);  // ✅ fixed
          }
        }
        await context.sync();

        //  Add cell validations for UDF_Demo sheet
        if (sheetDef.isDatesDemo) {
          const strLangRng = `${sheetDef.langCol}${_firstDataRow}:${sheetDef.langCol}${_lastDataRow}` 
          const strFmtOverrideRng = `${sheetDef.fmtOverrideCol}${_firstDataRow}:${sheetDef.fmtOverrideCol}${_lastDataRow}` 

          applyLangValidation(sheet, validLocaleList(), strLangRng);
          applyLangValidation(sheet, template.validation?.ParamListFormat, strFmtOverrideRng);

          applyLangValidation(sheet, template.validation?.ParamListTrueFalse, sheetDef.ordValidationCell);
          applyLangValidation(sheet, template.validation?.ParamListTrueFalse, sheetDef.isAllValidationCell);
          applyLangValidation(sheet, template.validation?.ParamListTrueFalse, sheetDef.dayNameValidationCell);
          applyLangValidation(sheet, template.validation?.ParamListTrueFalse, sheetDef.monthNameValidationCell);
          applyLangValidation(sheet, template.validation?.ParamListTrueFalse, sheetDef.yearNameValidationCell);
          applyLangValidation(sheet, template.validation?.ParamListFormat, sheetDef.formatTypeValidationCell);

          populateTestData(sheet, _firstDataRow);
        }

        if (sheetDef.isNumbersDemo) {
          const strLangRng = `${sheetDef.langCol}${_firstDataRow}:${sheetDef.langCol}${_lastDataRow}` 
          const strStyleRng = `${sheetDef.styleCol}${_firstDataRow}:${sheetDef.styleCol}${_lastDataRow}` 

          applyLangValidation(sheet, validLocaleList(), strLangRng);

          applyLangValidation(sheet, template.validation?.ParamListStyle, strStyleRng);

          populateTestData(sheet, _firstDataRow);
        }

      }
      // END OF CELLS LOOP ******************************

      // Apply named ranges (NEW)
      if (sheetDef.names) {
        await applyNames(context, sheet, sheetDef.names);
      }

      if (sheetDef.columnWidths) {
        applyColumnWidths(sheet, sheetDef.columnWidths);
      }

      if (sheetDef.rowHeights) {
        applyRowHeights(sheet, sheetDef.rowHeights);
      }

      if (sheetDef.mergedCells) {
        applyMergedCells(sheet, sheetDef.mergedCells);
      }

      if (sheetDef.isDefault) {
          sheet.activate();
      }

      const usedRange = sheet.getUsedRange();
      usedRange.format.autofitColumns();

      autofitAllColumnsOnSheet(sheet.name);

      const rowsToFreeze = sheetDef.name === "Dates_Demo" ? 4 : (sheetDef.name === "Numbers_Demo" ? 2 : 0);
      try {
        sheet.freezePanes.freezeRows(rowsToFreeze);
        mltkLogger.warn(`freezeTopRows: used freezeRows() for ${sheetName} rows=${rowsToFreeze}`);
      }
      catch {
        mltkLogger.warn(`freezeTopRows: freezeRows(${rowsToFreeze}) failed, no rows froozen`, e);
      }

    }
    // END OF SHEETS LOOP ******************************

    // Collect comments from template
    const comments = collectTemplateComments(template);

    // Write them into hidden sheet
    await writeCommentsSheet(context, comments);

    await context.sync();
    const templateMsg = `Template ${actionMsg} by a ${consMsg} click.`;
    mltkLogger.debug(templateMsg);
   
  });
}

/* Applies MergedCells for a sheet. */
function applyMergedCells(sheet, mergedList) {
  if (!mergedList) return;

  for (const address of mergedList) {
    try {
      const range = sheet.getRange(address);
      range.merge();
    } catch (e) {
      mltkLogger.debug(`Failed to merge ${address}`, e);
    }
  }
}

/* Applies named ranges for a sheet. */
async function applyNames(context, sheet, names) {
  for (const name in names) {
    const address = names[name];

    try {
      // Delete existing name if present
      const existing = context.workbook.names.getItemOrNullObject(name);
      existing.load("isNullObject");
      await context.sync();

      if (!existing.isNullObject) {
        existing.delete();
        await context.sync();
      }

      // Add new name
      const range = sheet.getRange(address);
      context.workbook.names.add(name, range);
      await context.sync();

    } catch (e) {
      mltkLogger.error(`Failed to create named range ${name} → ${address}`, e);
    }
  }
}

/* Applies simple formatting to a range.
    Supports: bold, italic, size, color, fill, hAlign, vAlign, borders.
*/
function applyFormatting(range, fmt) {
  if (!fmt) return;

  try {
    if (fmt.bold !== undefined) range.format.font.bold = fmt.bold;
    if (fmt.italic !== undefined) range.format.font.italic = fmt.italic;
    if (fmt.fontSize !== undefined) range.format.font.size = fmt.fontSize;
    if (fmt.color !== undefined) range.format.font.color = fmt.color;
    if (fmt.fill !== undefined) range.format.fill.color = fmt.fill;

    if (fmt.hAlign !== undefined) range.format.horizontalAlignment = fmt.hAlign;
    if (fmt.vAlign !== undefined) range.format.verticalAlignment = fmt.vAlign;

    // ⭐ Borders
    // if (fmt.borders) {
    //   const b = fmt.borders;
    //   if (b.top) range.format.borders.getItem("Top").style = b.top;
    //   if (b.bottom) range.format.borders.getItem("Bottom").style = b.bottom;
    //   if (b.left) range.format.borders.getItem("Left").style = b.left;
    //   if (b.right) range.format.borders.getItem("Right").style = b.right;
    // }

  } catch (e) {
    mltkLogger.error("Formatting failed:", e);
  }
}

/* Collects all comments from all sheets in the template.
   Returns an array of objects: { sheetName, address, text, author }
*/
function collectTemplateComments(template) {
  const list = [];

  for (const sheetDef of template.sheets) {
    const sheetName = sheetDef.name;

    if (!sheetDef.cells) continue;

    for (const address in sheetDef.cells) {
      const def = sheetDef.cells[address];
      if (def.comment && def.comment.text) {
        list.push({
          sheetName,
          address,
          text: def.comment.text,
          author: def.comment.author || ""
        });
      }
    }
  }

  return list;
}

/* Writes comments into a hidden sheet named "_Comments". */
async function writeCommentsSheet(context, comments) {
  if (!comments || comments.length === 0) return;

  // Try to get existing sheet
  let sheet;
  try {
    sheet = context.workbook.worksheets.getItem("_Comments");
    sheet.load("name");
    await context.sync();
  } catch (e) {
    // Create new sheet
    sheet = context.workbook.worksheets.add("_Comments");
    sheet.load("name");
    await context.sync();
  }

  /*
  // Clear sheet
  const used = sheet.getUsedRangeOrNullObject();
  used.load("isNullObject");
  await context.sync();
  if (!used.isNullObject) {
    used.clear(Excel.ClearApplyTo.contents);
  }
*/

// Write comments (Append)
  const usedRange = sheet.getUsedRangeOrNullObject();
  usedRange.load("rowCount");  // usedRange.load("rowCount", "columnCount");  would load both row and column counts
  await context.sync();

  let lastRow = usedRange.isNullObject ? 0 : usedRange.rowCount;
  let row = lastRow + 1;
  // let lastColumn = usedRange.isNullObject ? 0 : usedRange.rowColumn;
  // let column = lastColumn + 1;

  // If lastRow === 0 then there is no data in sheet (i.e. a new sheet has just been created).  Therefore, write a header row
  if (lastRow === 0) {
    const range = sheet.getRange("A1:D1");
    range.values = [["WorksheetName", "Cell", "Comment", "Author"]];
    row++;
  }

  for (const c of comments) {
    const range = sheet.getRange(`A${row}:D${row}`);
    range.values = [[c.sheetName, c.address, c.text, c.author]];
    row++;
  }

  // We only need columns for tis aaction on usedRange.  If data had just been appended, usedRange is not null and we could have used it for autoFitColumns() unless 
  // we had aded columns (which we have not done here).  But if usedRange was null and a new worksheet was created, the autofitColumns() on usedRange would fail. 
  // To avoid this, let's define a new usedRange just in case 
  const newUsedRange = sheet.getUsedRangeOrNullObject();
  newUsedRange.format.autofitColumns();

  // Hide sheet
  // sheet.visibility = Excel.SheetVisibility.hidden;
}

function applyColumnWidths(sheet, widths) {
  if (!widths) return;

  for (const col in widths) {
    try {
      const range = sheet.getRange(`${col}:${col}`);
      range.format.columnWidth = widths[col];
    } catch (e) {
      mltkLogger.debug(`Failed to set column width for ${col}`, e);
    }
  }
}

function applyRowHeights(sheet, heights) {
  if (!heights) return;

  for (const row in heights) {
    try {
      const range = sheet.getRange(`${row}:${row}`);
      range.format.rowHeight = heights[row];
    } catch (e) {
      mltkLogger.debug(`Failed to set row height for row ${row}`, e);
    }
  }
}

function applyLangValidation(sheet, list, strRng) {

  mltkLogger.debug("Validation List =", list);

  // Convert array of objects → array of strings
  // const localeList = list.map(x => x.locale);
  // const source = localeList.join(",");
  const source = list.join(",");   // now list is an array of strings
  const langRange = sheet.getRange(strRng);  // or dynamic
  langRange.dataValidation.rule = {
    list: {
      inCellDropDown: true,
      source
    }
  };
}

function populateTestData(sheet, startRow = 5 ) {

  mltkLogger.debug(`Entering populateTestData...`)  
  mltkLogger.debug(`... sheet.name: ${sheet.name}`)  

  if (sheet.name === "Dates_Demo") {
    mltkLogger.debug(`... in if stmt for Dates_Demo`)  

    TestData.forEach((row, i) => {
      const r = startRow + i;

      sheet.getRange(`A${r}`).values = [[row.ID]];
      sheet.getRange(`B${r}`).values = [[row.First]];
      sheet.getRange(`C${r}`).values = [[row.Last]];
      sheet.getRange(`D${r}`).values = [[row.Lang]];
      sheet.getRange(`E${r}`).values = [[row.DOB]];
      sheet.getRange(`F${r}`).values = [[row.FormatType]];
      sheet.getRange(`G${r}`).values = [[row.CustomFormat]];
    });
  }

  if (sheet.name === "Numbers_Demo") {
    mltkLogger.debug(`... in if stmt for Numbers_Demo`)  
    TestDataNumbers.forEach((row, i) => {
      const r = startRow + i;

      sheet.getRange(`A${r}`).values = [[row.ID]];
      sheet.getRange(`B${r}`).values = [[row.First]];
      sheet.getRange(`C${r}`).values = [[row.Last]];
      sheet.getRange(`D${r}`).values = [[row.Number]];
      sheet.getRange(`E${r}`).values = [[row.LocaleTag]];
      sheet.getRange(`F${r}`).values = [[row.style]];
      sheet.getRange(`G${r}`).values = [[row.dec]];
    });
  }  

}

// Autofit all columns on a worksheet (Dates_Demo example)
async function autofitAllColumnsOnSheet(sheetName) {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getItem(sheetName);
    const used = sheet.getUsedRange();
    used.load("address"); // optional, for debugging
    await context.sync();

    // Autofit the columns that intersect the used range
    used.getEntireColumn().format.autofitColumns();
    await context.sync();

    console.log(`Autofit columns on ${sheetName} (used range ${used.address})`);
  });
}