import * as funcs from "./btnCommands.js";
import { loadTemplateById, applyUDFTemplate } from "../functions/templates/loader.js";

// Ribbon callback (Excel calls one of these functions when user clicks a ribbon button)

// Trigerred by Ribbon Button "Get UDF Template Obj"
// Creates a template for testing UDFs using a template object.
async function loadTemplateUDF(event) {
  const templateId = "templateUDF";   // or from a dropdown
  const template = loadTemplateById(templateId);

  if (!template) {
    console.error("Template not found:", templateId);
    return;
  }
  await applyUDFTemplate(template, "ribbon");
  event.completed();
}

// Trigerred by Ribbon Button "Get FileName"
// Writes the file full name in the current cell.
function writeFullName(event) {
    funcs.writeWorkbookFullName();
    event.completed();
}

// Associates all commands with Office(Excel) so they can be invoked by a custom Ribbon buttons
Office.onReady(() => {
  Office.actions.associate("loadTemplateUDF", loadTemplateUDF);
  Office.actions.associate("writeFullName", writeFullName);
});

